const sources = [
  {
    name: 'open.er-api.com',
    url: 'https://open.er-api.com/v6/latest/USD',
    pick: (d) => d?.rates,
  },
];

const errors = [];
for (const s of sources) {
  try {
    const res = await fetch(s.url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    const rates = s.pick(data);
    if (!rates?.IDR || !rates?.EUR) throw new Error('Rates not found');
    return { 
      rate_idr: rates.IDR, 
      rate_eur: rates.EUR, 
      source: s.name,
      timestamp: new Date().toISOString()
    };
  } catch (err) {
    errors.push(`${s.name}: ${err.message}`);
  }
}
throw new Error(`Fetch failed — ${errors.join(' | ')}`);

const today = inputs.timestamp.split('T')[0];
const archiveEntry = {
  date: today,
  usd_idr: inputs.rate_idr,
  usd_eur: inputs.rate_eur,
  source: inputs.source,
  archived_at: new Date().toISOString(),
};

// Simulasi: pretend save ke file
// Dalam production: append ke database atau write file
const simulatedFilePath = `/archive/exchange-rates/${today}.json`;

const archive_result = `## ✅ Archive Success

**Saved:** ${today}

\`\`\`json
${JSON.stringify(archiveEntry, null, 2)}
\`\`\`

**Simulated path:** \`${simulatedFilePath}\`

**Status:** Stored in memory (simulate)
- USD→IDR: ${archiveEntry.usd_idr.toLocaleString('id-ID')}
- USD→EUR: ${archiveEntry.usd_eur.toFixed(4)}
- Timestamp: ${archiveEntry.archived_at}

---

✨ Ready to view di morning report!
`;

console.log(`✓ Archive entry created for ${today}`);
return { archive_result };
